create table public.metrc_harvests (id bigint generated by default as identity primary key,"license" text not null,"metrc_id" bigint not null,"name" text,"harvest_start" date,"wet_weight" numeric(14,3),"waste_weight" numeric(14,3),"package_count" integer,"raw" jsonb not null,"synced_at" timestamp with time zone not null default now(),"source_state" text not null default 'active'::text,flower_room text, unique(license,metrc_id));
create table public.metrc_packages (id bigint generated by default as identity primary key,"license" text not null,"tag" text not null,"item_name" text,"quantity" numeric(14,3),"uom" text,"location" text,"packaged_on" date,"lab_testing_state" text,"finished" boolean,"raw" jsonb not null,"synced_at" timestamp with time zone not null default now(),"source_state" text not null default 'active'::text,"provenance" text not null default 'metrc api'::text,"report_as_of" date, unique(license,tag));
create table public.metrc_plant_batches (id bigint generated by default as identity primary key,"license" text not null,"name" text not null,"strain" text,"count" integer,"batch_type" text,"planted_on" date,"raw" jsonb not null,"synced_at" timestamp with time zone not null default now(),"source_state" text not null default 'active'::text, unique(license,name));
create table public.metrc_plants (id bigint generated by default as identity primary key,"license" text not null,"tag" text not null,"strain" text,"phase" text,"room" text,"planted_on" date,"raw" jsonb not null,"synced_at" timestamp with time zone not null default now(),"source_state" text not null default 'active'::text,"provenance" text not null default 'metrc api'::text,"report_as_of" date, unique(license,tag));
create table public.metrc_transfers (id bigint generated by default as identity primary key,"license" text not null,"manifest_number" text not null,"direction" text not null,"shipper" text,"recipient" text,"created_on" date,"raw" jsonb not null,"synced_at" timestamp with time zone not null default now(), unique(license,manifest_number,direction));
